if(ro===undefined||ro===null||ro==="") return siFail(st,"INVALID_UPSTREAM_CONTEXT","MISSING_ROUTING_OUTCOME");
if(SKIP.indexOf(ro)!==-1){
  // Section 5 canonical SKIP result; no RUN validation, no registry, no desired mutation.
