}
if(RUN.indexOf(ro)===-1) return siFail(st,"INVALID_UPSTREAM_CONTEXT","ROUTING_OUTCOME_NOT_IN_CLOSED_SETS");
return [{json:Object.assign({},st,{_si_gate:"RUN"})}];

