// ===== Increment 6 deterministic reduction + assembly (Sections 122-161) - NO AI AUTHORITY =====
const LOOKBACK={HIRING_SIGNAL:180,RECRUITING_EXPANSION:180,WORKFORCE_REDUCTION:180,ORGANIZATIONAL_CHANGE:180,
 COMPANY_EXPANSION:365,FUNDING_OR_INVESTMENT:365,PRODUCT_OR_MARKET_LAUNCH:365,PARTNERSHIP_OR_ACQUISITION:365,
 OTHER_RELEVANT:180,UNKNOWN:null};
const C_CONSIST={CONSISTENT:0,CONFLICT:1}, C_FRESH={CURRENT:0,UNKNOWN:1,STALE:2}, C_SRC={FIRST_PARTY:0,THIRD_PARTY:1},
      C_TIME={PRESENT:0,FUTURE:1,PAST:2,UNKNOWN:3}, C_BIND={CONFLICT:0,UNRESOLVED:1};
const CAVEAT_ORDER=["HR_DISCOVERY_FAILED","HR_DISCOVERY_EMPTY","NO_CURRENT_SIGNALS","THIRD_PARTY_EVIDENCE_PRESENT","CLASSIFICATION_CONFLICT_PRESENT"];
// ---------- helper utils ----------
function lex(a,b){ return siUtf8Compare(a,b); }
function utcDate(ts){ if(!ts||typeof ts!=="string") return null;
  var m=ts.match(/^(\d{4}-\d{2}-\d{2})/); if(!m) return null; return m[1]; }
function addDays(iso,n){ var d=new Date(iso+"T00:00:00Z"); d.setUTCDate(d.getUTCDate()+n);
  return d.toISOString().slice(0,10); }
// ---------- §122-125 consolidation ----------
function consolidateGroup(cands){
  if(!cands||!cands.length) return {consolidated:false,reason:"EMPTY_GROUP"};
  var types={}, attrs={}, ivs={}, ivList=[];
  for(const c of cands){ types[c.signal_type]=1; attrs[c.target_attribution]=1;
    var iv=c.candidate_event_interval;
    if(iv){ var k=iv.interval_start+"|"+iv.interval_end; if(!ivs[k]){ivs[k]=1; ivList.push(iv);} } }
  var tk=Object.keys(types);
  var classification_status=(tk.length===1)?"CONSISTENT":"CONFLICT";
  var signal_type=(tk.length===1)?tk[0]:"UNKNOWN";
  var ak=Object.keys(attrs);
  var attribution_binding = (ak.length===1&&ak[0]==="TARGET_ACCOUNT")?"CONSISTENT_TARGET"
    : (ak.length===1&&ak[0]==="OTHER_ORGANIZATION")?"CONSISTENT_OTHER"
    : (ak.length===1&&ak[0]==="AMBIGUOUS")?"CONSISTENT_AMBIGUOUS" : "CONFLICT";
  var event_date_status = (ivList.length===0)?"UNAVAILABLE":(ivList.length===1)?"CONSISTENT":"CONFLICT";
  var first=cands[0];
  return {consolidated:true,observation_key:first.observation_key,source_entity_id:first.source_entity_id,
    source_snapshot_id:first.source_snapshot_id,signal_type:signal_type,classification_status:classification_status,
    attribution_binding:attribution_binding,event_date_status:event_date_status,
    event_date:(event_date_status==="CONSISTENT")?ivList[0]:null,
    evidence_excerpt:first.grounded_evidence_text,source_type:first.source_type,source_url:first.source_url,
    candidate_count:cands.length,signal_target_binding:first.signal_binding};
}
function consolidateAll(cands){
  var g={}; for(const c of (cands||[])){ var k=c.observation_key; if(!g[k]) g[k]=[]; g[k].push(c); }
  return Object.keys(g).sort(lex).map(function(k){ return consolidateGroup(g[k]); });
}
// ---------- §101-103 freshness / timing ----------
function freshness(signal_type,published_at,retrieved_at){
  var D=utcDate(retrieved_at); if(!D) return "UNKNOWN";
  var N=LOOKBACK[signal_type]; if(N===null||N===undefined) return "UNKNOWN";
  if(!published_at) return "UNKNOWN";
