  }
}

function header(headers, name) {
  if (!headers || typeof headers !== "object") return null;

  const k = Object.keys(headers).find(
    x => x.toLowerCase() === name.toLowerCase()
  );

  if (!k) return null;

  const v = headers[k];

  return Array.isArray(v)
    ? v.join(", ")
    : (v === undefined || v === null ? null : String(v));
}

function clamp(s, n) {
  s = String(s || "");
  return s.length > n ? s.slice(0, n) + "…" : s;
}

function parseJsonMaybe(v) {
  if (v === null || v === undefined) return null;

  if (typeof v === "object") return v;

  if (typeof v !== "string") return null;

  const s = v.trim();

  if (!s) return null;

  try {
    return JSON.parse(s);
  } catch (e) {
    return null;
  }
}

function isResponseLike(v) {
  return !!(
    v &&
    typeof v === "object" &&
    (
      v.object === "response" ||
      (typeof v.id === "string" && v.id.startsWith("resp_")) ||
      Array.isArray(v.output) ||
      (v.usage && typeof v.usage === "object")
    )
  );
}

function resolveResponseEnvelope(x) {
  const seen = [];

  function push(label, val) {
    if (val !== undefined && val !== null) {
      seen.push({ label, val });
    }
  }

  push("incoming.body", x.body);

  if (x.body && typeof x.body === "object") {
    push("incoming.body.body", x.body.body);
  }

  push("incoming.response", x.response);
  push("incoming.data", x.data);
  push("incoming", x);

  for (const c of seen) {
    let cur = c.val;

    for (let depth = 0; depth < 3; depth++) {
      const parsed = parseJsonMaybe(cur);

      if (parsed === null) break;

      if (isResponseLike(parsed)) {
        return {
          body: parsed,
          from: c.label + (depth ? ":json_parse_" + depth : "")
        };
      }

      if (
        parsed &&
        typeof parsed === "object" &&
        parsed.body !== undefined
      ) {
        cur = parsed.body;
        continue;
      }

      break;
    }
  }

  const first = parseJsonMaybe(x.body);

  if (first && typeof first === "object") {
    return {
      body: first,
      from: "incoming.body:fallback"
    };
  }

  return {
    body: x,
    from: "incoming:fallback"
  };
}

