  return null;
}
const batchEc=classifyBatchFailure();
const successMap={};
for(const r of results){
  const k=key(r&&r.url);
  if(k && successMap[k]===undefined) successMap[k]=r;
}
const failedMap={};
for(const r of failed){
  const k=key(r&&r.url);
  if(k && failedMap[k]===undefined) failedMap[k]=r;
}

// Publication-date bridge:
// Tavily Search already returns provider_published_at. Admit it as trusted Fetch publication
// metadata only after the exact requested_source_key has a successful Tavily Extract result.
// Conflicting dates are preserved as separate candidates; the existing publication resolver
// will deterministically return CONFLICT instead of choosing one silently.
const pubByRequestedSourceKey={};
const searchByQuery=(st._si_search_by_query&&typeof st._si_search_by_query==="object")?st._si_search_by_query:{};
for(const qid of Object.keys(searchByQuery)){
  const sr=(searchByQuery[qid]&&Array.isArray(searchByQuery[qid].results))?searchByQuery[qid].results:[];
  for(const x of sr){
    const rsk=x&&x.requested_source_key;
    if(!rsk) continue;
    const ds=Array.isArray(x.provider_published_at_candidates)
      ? x.provider_published_at_candidates
      : ((typeof x.provider_published_at==="string"&&x.provider_published_at)?[x.provider_published_at]:[]);
    if(!pubByRequestedSourceKey[rsk]) pubByRequestedSourceKey[rsk]=[];
    for(const d of ds){
      if(typeof d==="string" && d && pubByRequestedSourceKey[rsk].indexOf(d)===-1)
        pubByRequestedSourceKey[rsk].push(d);
    }
  }
}
for(const rsk of Object.keys(pubByRequestedSourceKey)) pubByRequestedSourceKey[rsk].sort();

const out=[];
for(let i=0;i<ops.length;i++){
  const op=ops[i]||{};
  const requested=String(op.validated_transport_url||op.canonical_requested_url||"");
  const k=key(requested);
  let r=successMap[k]||null;
  let f=failedMap[k]||null;
  // tolerate a provider-added/removed trailing slash if exact normalized key still missed
  if(!r&&!f){
    const alt=k.endsWith("/")?k.slice(0,-1):k+"/";
    r=successMap[alt]||null; f=failedMap[alt]||null;
  }
  let ec=batchEc;
  let raw=null, finalUrl=requested, providerError=null;
  if(!ec && r){
    raw=(r.raw_content===undefined||r.raw_content===null)?"":String(r.raw_content);
    finalUrl=String(r.url||requested);
    if(!raw.trim()) ec="INVALID_RESPONSE";
  }else if(!ec && f){
    ec="TARGET_EXTRACTION_FAILED";
    providerError=txt(f.error||f.message||f).slice(0,500);
  }else if(!ec){
    ec="INVALID_RESPONSE";
    providerError="TAVILY_EXTRACT_RESULT_MISSING_FOR_REQUESTED_URL";
  }
  const pubDates=(!ec && op.requested_source_key && pubByRequestedSourceKey[op.requested_source_key])
    ? pubByRequestedSourceKey[op.requested_source_key].slice() : [];
  const pubCandidates=pubDates.map(function(d){
    return {
      raw_value:d,
      candidate_origin:"TRUSTED_PROVIDER_PUBLICATION_DATE",
      semantic_type:"PUBLICATION_DATE",
      adapter_trust:"TRUSTED"
    };
  });
  const env=(!ec)?{
    status_code:null,
    content_type:"text/plain; charset=utf-8",
    final_url:finalUrl,
    retrieved_at:now,
    body:raw,
    structured_identity_metadata:{organization_refs:[]},
    raw_published_date_candidates:pubCandidates,
    response_headers:{}
  }:null;
  out.push({json:Object.assign({},st,{
    _si_logical_fetch_operation:op,
    _si_current_logical_fetch_operation:op,
    _si_fetch_request_prepared:true,
    _si_fetch_request_url:requested,
    _si_fetch_final_url:finalUrl,
    _si_fetch_retrieved_at:now,
    _si_fetch_body:raw,
    _si_fetch_envelope:env,
    _si_fetch_error_class:ec,
    _si_fetch_http_status:null,
    _si_fetch_provider_http_status:status,
    _si_fetch_content_type:env?env.content_type:null,
    _si_fetch_response_bytes:raw===null?0:Array.from(raw).length,
    _si_fetch_logical_attempts_used_delta:1,
    _si_fetch_network_requests_used_delta:(i===0 && ops.length>0)?1:0,
    _si_fetch_transport_provider:"TAVILY_EXTRACT",
    _si_fetch_provider_error:providerError,
    _si_fetch_redirect_count:null,
    _si_fetch_redirect_hops:[],
    _si_tavily_extract_metadata:{
      request_id:body&&body.request_id||null,
      response_time:body&&body.response_time||null,
      usage:body&&body.usage||null,
      batch_size:ops.length,
      publication_date_bridge_policy:"MATCHED_REQUESTED_SOURCE_KEY_AFTER_SUCCESSFUL_FETCH_V1",
      publication_date_candidate_count:pubCandidates.length
    },
    terminal_state:null
  })});
}
if(ops.length===0){
  return [{json:Object.assign({},st,{
    _si_no_fetch_ops:true,
    _si_fetch_network_requests_used_delta:0
  })}];
}
return out;
